#!/usr/bin/env python3
"""Structural stubs for the RSCH-1 BLIND arm.

Prereg §3 makes BLIND — not 1/12 — the baseline C1 is measured against: it is the
floor *this attacker* reaches from priors and task framing alone, with no access
to the artifact's content. So the stub has to carry the artifact's shape and
nothing else.

Two properties are load-bearing and both are enforced here rather than trusted.

**Generated by code, never hand-written** (§3, explicit). A hand-written stub can
be tuned toward a flattering floor — trim a detail here, round a count there, and
BLIND drops, which widens the husk−blind gap the experiment is trying to measure.
`render()` is a pure function of the source bytes and the language.

**No identifiers, no literals, no comments** (§3, explicit). The stub is numeric
by construction, and `assert_content_free()` re-checks the rendered text against
the source's own token inventory before it is allowed out. That check is the
point: a stub that leaked one identifier would quietly convert the baseline into
a second husk arm and every verdict downstream would be wrong in the flattering
direction.

    python3 evals/blind_stub.py corpus/stacks/api/internal/api/branches.go
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from counters import count  # noqa: E402

# An HTTP handler in the Go house style takes (http.ResponseWriter, *http.Request).
# Counted separately from `funcs` because §3 names handler count specifically: it
# is the one counter that says "this is service code" rather than "this is code."
_GO_HANDLER = re.compile(r"func\s*\([^)]*\)\s*\w+\s*\(\s*\w+\s+http\.ResponseWriter\s*,")
# A React component in the TSX house style: exported, capitalised, returns JSX.
_TS_COMPONENT = re.compile(r"^\s*export\s+function\s+[A-Z]\w*\s*\(", re.M)

# counters.py's `imports` and `exports` are computed for a different job — the
# input-vs-output DELTA in model selection, where a consistent undercount cancels.
# Here they are ABSOLUTE signals handed to an attacker, so the undercount does not
# cancel and has to go. Two specific gaps, fixed locally so counters.py's numbers
# stay reproducible for the runs that already cite them:
#
#   imports  — counters.py matches the `import (` block opener, so a Go file with
#              six imports in one block scores 1.
#   exports  — Go has no `export` keyword; every Go file scored 0, a constant that
#              tells the attacker nothing. Go exports by capitalising, so that is
#              what gets counted.
_GO_IMPORT_BLOCK = re.compile(r"^import\s*\(([^)]*)\)", re.M | re.S)
_GO_IMPORT_SINGLE = re.compile(r"^import\s+(?:\w+\s+)?[\"`]", re.M)
_GO_IMPORT_LINE = re.compile(r"^\s*(?:[\w.]+\s+)?[\"`][^\"`]+[\"`]\s*$", re.M)
_GO_EXPORTED = re.compile(
    r"^(?:func\s+(?:\([^)]*\)\s*)?([A-Z]\w*)|type\s+([A-Z]\w*)|"
    r"(?:var|const)\s+([A-Z]\w*))", re.M)


def _go_imports(text: str) -> int:
    n = sum(len(_GO_IMPORT_LINE.findall(b)) for b in _GO_IMPORT_BLOCK.findall(text))
    return n + len(_GO_IMPORT_SINGLE.findall(text))


def _go_exports(text: str) -> int:
    return sum(1 for m in _GO_EXPORTED.findall(text) if any(m))

# Identifier-ish tokens the template itself contributes. Anything in the rendered
# stub outside this set would have to have come from the source.
_TEMPLATE_TOKENS = {
    "structural", "profile", "language", "lines", "bytes", "functions", "handlers",
    "components", "structs", "classes", "interfaces", "types", "imports", "exports",
    "string", "literals", "max", "brace", "depth", "go", "ts", "tsx",
}

_WORD = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def profile(text: str, language: str) -> dict[str, int | str]:
    """The numeric shape of one artifact. Pure function of (bytes, language)."""
    c = count(text, language)
    lang = language.lower()
    if lang == "go":
        nested = len(_GO_HANDLER.findall(text))
        imports, exports = _go_imports(text), _go_exports(text)
    else:
        nested = len(_TS_COMPONENT.findall(text))
        imports, exports = c["imports"], c["exports"]
    return {
        "language": lang,
        "lines": c["lines"],
        "bytes": c["bytes"],
        "functions": c["funcs"],
        # One key, two names: "handlers" in Go, "components" in TS/TSX. The label
        # differs because the thing counted differs; calling a React component a
        # handler would misdescribe the shape to the attacker.
        "handlers_or_components": nested,
        "structs_or_classes": c["structs"],
        "interfaces_or_types": c["interfaces"],
        "imports": imports,
        "exports": exports,
        "string_literals": c["string_literals"],
        "max_brace_depth": c["max_brace_depth"],
    }


def render(text: str, language: str) -> str:
    """The stub as the attacker sees it. Numeric by construction."""
    p = profile(text, language)
    lang = str(p["language"])
    second = "handlers" if lang == "go" else "components"
    third = "structs" if lang == "go" else "classes"
    fourth = "interfaces" if lang == "go" else "types"
    return (
        "STRUCTURAL PROFILE\n"
        f"language: {lang}\n"
        f"lines: {p['lines']}\n"
        f"bytes: {p['bytes']}\n"
        f"functions: {p['functions']}\n"
        f"{second}: {p['handlers_or_components']}\n"
        f"{third}: {p['structs_or_classes']}\n"
        f"{fourth}: {p['interfaces_or_types']}\n"
        f"imports: {p['imports']}\n"
        f"exports: {p['exports']}\n"
        f"string literals: {p['string_literals']}\n"
        f"max brace depth: {p['max_brace_depth']}\n"
    )


def assert_content_free(stub: str) -> None:
    """Fail hard if the stub carries anything but template words and numbers.

    Cheap, and it guards the one failure that would silently invalidate every
    verdict: a BLIND item that is not actually blind.
    """
    leaked = {w for w in _WORD.findall(stub) if w.lower() not in _TEMPLATE_TOKENS}
    if leaked:
        raise AssertionError(f"BLIND stub is not content-free, leaked: {sorted(leaked)}")


def stub_for(path: Path, language: str | None = None) -> str:
    lang = language or path.suffix.lstrip(".")
    s = render(path.read_text(encoding="utf-8"), lang)
    assert_content_free(s)
    return s


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(__doc__.strip().splitlines()[-1].strip(), file=sys.stderr)
        raise SystemExit(2)
    for arg in sys.argv[1:]:
        p = Path(arg)
        print(f"=== {p} ===")
        print(stub_for(p), end="")
